      "evidence": [
        {"source": "netlist", "quote": "(node (ref \"FCC2\") (pin \"11\") (pinfunction \"VDD\") (pintype \"power_in\")) on net unconnected-(FCC2-VDD-Pad11)"},
        {"source": "spec", "quote": "3V3 feeds both MCUs (FCC, NAVC) and all I2C sensor ICs"}
      ],
      "impact": "The MCUs will not be powered and the board will not function.",
      "confidence": 0.99
    },
    {
      "category": "bridged_nets",
      "components": ["FCC2", "UART3_FCC2"],
      "pins": ["FCC2.48", "FCC2.73", "UART3_FCC2.3", "UART3_FCC2.4"],
      "nets": ["NET0125", "NET0020"],
      "observed": "FCC2 VCAP pins (48 and 73) are connected to UART3_FCC2 connector pins 3 and 4 on nets NET0125 and NET0020.",
      "expected": "VCAP pins should be decoupled to GND with capacitors, and UART3_FCC2 pins 3/4 should be connected to the MCU's UART3 TX/RX pins.",
      "evidence": [
        {"source": "netlist", "quote": "(node (ref \"FCC2\") (pin \"48\") (pinfunction \"VCAP\") (pintype \"power_out\")) (node (ref \"UART3_FCC2\") (pin \"3\") (pinfunction \"Pin_3\") (pintype \"passive\")) on net NET0125"},
        {"source": "spec", "quote": "UART2 + I2C + GPIO between the two MCUs"}
      ],
      "impact": "The UART3 connector is not usable for UART communication, and the MCU's internal core voltage regulator lacks decoupling, likely causing unstable operation or damage.",
      "confidence": 0.98
    }
